  yellow: 'bg-yellow-50 border-yellow-200 text-yellow-700',
  pink: 'bg-pink-50 border-pink-200 text-pink-700',
}

function BadgeCard({ achievement, unlocked }) {
  return (
    <div
      className={`rounded-xl border-2 p-4 text-center transition ${
        unlocked
          ? `${COLOR_STYLES[achievement.color]} border-2`
          : 'bg-slate-50 border-slate-200 text-slate-400'
      } ${unlocked ? 'shadow-md' : 'opacity-60'}`}
    >
      <div className="text-4xl mb-2">{achievement.icon}</div>
      <p className="font-semibold text-sm">{achievement.title}</p>
      <p className="text-xs mt-1 opacity-75">{achievement.description}</p>
      {unlocked && <p className="text-xs font-bold mt-2">🎉 Unlocked!</p>}
    </div>
  )
}

export default function AchievementBadges({ stats = {} }) {
  const unlockedBadges = Object.values(ACHIEVEMENTS).filter((achievement) =>
    achievement.condition(stats)
  )

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h3 className="text-lg font-bold text-slate-900 mb-1">Achievements</h3>
        <p className="text-sm text-slate-600">
          {unlockedBadges.length} of {Object.keys(ACHIEVEMENTS).length} unlocked
        </p>
      </div>

      {/* Progress Bar */}
      <div className="space-y-2">
        <div className="h-3 w-full overflow-hidden rounded-full bg-slate-100">
          <div
            className="h-full bg-gradient-to-r from-emerald-500 via-blue-500 to-purple-500 transition-all duration-500"
            style={{ width: `${(unlockedBadges.length / Object.keys(ACHIEVEMENTS).length) * 100}%` }}
          />
        </div>
        <p className="text-xs text-slate-500 text-right">
          {Math.round((unlockedBadges.length / Object.keys(ACHIEVEMENTS).length) * 100)}% complete
        </p>
      </div>

      {/* Badges Grid */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">
        {Object.values(ACHIEVEMENTS).map((achievement) => (
          <BadgeCard
            key={achievement.id}
            achievement={achievement}
            unlocked={unlockedBadges.some((b) => b.id === achievement.id)}
          />
        ))}
      </div>

      {/* Next Goal */}
      {unlockedBadges.length < Object.keys(ACHIEVEMENTS).length && (
        <div className="rounded-xl border border-slate-200 bg-slate-50 p-4">
          <p className="text-sm font-semibold text-slate-800 mb-2">🎯 Next Goal</p>
          <p className="text-xs text-slate-600">
            Complete {Object.keys(ACHIEVEMENTS).length - unlockedBadges.length} more achievement
            {Object.keys(ACHIEVEMENTS).length - unlockedBadges.length > 1 ? 's' : ''} to unlock all badges!
          </p>
        </div>
      )}

      {/* All Unlocked Celebration */}
      {unlockedBadges.length === Object.keys(ACHIEVEMENTS).length && (
        <div className="rounded-xl border-2 border-yellow-300 bg-gradient-to-r from-yellow-50 to-amber-50 p-4 text-center">
          <p className="text-lg font-bold text-yellow-700">👑 ACHIEVEMENT MASTER! 👑</p>
          <p className="text-sm text-yellow-600 mt-1">You've unlocked all achievements. You're a health legend!</p>
        </div>
      )}
    </div>
  )
}

import { AlertCircle, AlertTriangle, Info, X } from 'lucide-react'
import { useState, useEffect } from 'react'
import { generateBiomarkerAlerts, getAlertColor, getAlertIcon } from '../lib/biomarker-alerts'

export default function BiomarkerAlertsDisplay({ biomarkers, previousBiomarkers, userPreferences }) {
  const [alerts, setAlerts] = useState([])
  const [dismissedAlerts, setDismissedAlerts] = useState(new Set())

  useEffect(() => {
    if (biomarkers?.length > 0) {
      const generatedAlerts = generateBiomarkerAlerts(biomarkers, previousBiomarkers)
      setAlerts(generatedAlerts)
    }
  }, [biomarkers, previousBiomarkers])

  const visibleAlerts = alerts.filter(alert => !dismissedAlerts.has(alert.id))

  const dismissAlert = (alertId) => {
    setDismissedAlerts(prev => new Set([...prev, alertId]))
  }

  const getIconComponent = (status) => {
    if (status === 'critical') return <AlertCircle size={20} />
    if (status === 'warning') return <AlertTriangle size={20} />
    return <Info size={20} />
  }

  const statusOrder = { critical: 0, warning: 1, info: 2 }
  const sortedAlerts = [...visibleAlerts].sort((a, b) => statusOrder[a.status] - statusOrder[b.status])

  if (sortedAlerts.length === 0) {
    return null
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      {sortedAlerts.map((alert) => {
        const bgColor = alert.status === 'critical'
          ? '#fef2f2'
          : alert.status === 'warning'
            ? '#fffbeb'
            : '#f0f9ff'

        const borderColor = getAlertColor(alert.status)
        const textColor = alert.status === 'critical'
          ? '#7f1d1d'
          : alert.status === 'warning'
            ? '#78350f'
            : '#0c2a47'

        return (
          <div
            key={alert.id}
            style={{
              padding: '14px 16px',
              background: bgColor,
              border: `2px solid ${borderColor}`,
              borderRadius: '10px',
              display: 'flex',
              gap: '12px',
              alignItems: 'flex-start'
            }}
          >
            {/* Icon */}
            <div style={{
              color: borderColor,
              flexShrink: 0,
              marginTop: '2px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}>
              {getIconComponent(alert.status)}
            </div>

            {/* Content */}
            <div style={{ flex: 1 }}>
              <div style={{
                fontSize: '14px',
                fontWeight: 600,
                color: textColor,
                marginBottom: '4px'
              }}>
                {alert.biomarkerName}
              </div>
              <div style={{
                fontSize: '13px',
                color: textColor,
                lineHeight: 1.4,
                marginBottom: '8px'
              }}>
                {alert.message}
              </div>

              {/* Action Button */}
              {alert.action && (
                <button style={{
                  padding: '6px 12px',
                  background: borderColor,
                  color: '#fff',
                  border: 'none',
                  borderRadius: '6px',
                  fontSize: '12px',
                  fontWeight: 600,
                  cursor: 'pointer',
                  transition: 'opacity 200ms'
                }}
                onMouseEnter={(e) => e.target.style.opacity = '0.9'}
                onMouseLeave={(e) => e.target.style.opacity = '1'}
                >
                  {alert.action}
                </button>
              )}
            </div>

            {/* Dismiss Button */}
            <button
              onClick={() => dismissAlert(alert.id)}
              style={{
                background: 'none',
                border: 'none',
                cursor: 'pointer',
                color: textColor,
                padding: '4px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexShrink: 0,
                opacity: 0.6,
                transition: 'opacity 200ms'
              }}
              onMouseEnter={(e) => e.target.style.opacity = '1'}
              onMouseLeave={(e) => e.target.style.opacity = '0.6'}
              title="Dismiss this alert"
            >
              <X size={18} />
            </button>
          </div>
        )
      })}

      {/* Summary */}
      {sortedAlerts.length > 0 && (
        <div style={{
          marginTop: '8px',
          padding: '12px',
          background: '#f8fafc',
          borderRadius: '8px',
          fontSize: '12px',
          color: '#64748b',
          display: 'flex',
          alignItems: 'center',
          gap: '8px'
        }}>
          <span style={{ fontWeight: 600 }}>
            {sortedAlerts.filter(a => a.status === 'critical').length > 0
              ? '⚠️ Review critical alerts above'
              : '📊 ' + sortedAlerts.length + ' alert' + (sortedAlerts.length !== 1 ? 's' : '')}
          </span>
        </div>
      )}
    </div>
  )
}

