export default function HealthTipsDisplay({ biomarkers, userContext }) {
  const [tips, setTips] = useState([])
  const [loading, setLoading] = useState(true)
  const [pendingMessage, setPendingMessage] = useState('')
  const [pendingJobId, setPendingJobId] = useState(null)
  const [selectedCategory, setSelectedCategory] = useState('all')
  const [expandedTip, setExpandedTip] = useState(null)
  const biomarkersKey = JSON.stringify((biomarkers || []).map((b) => ({
    name: b?.name,
    value: b?.value,
    status: b?.status,
    category: b?.category,
  })))
  const userContextKey = JSON.stringify({
    age: userContext?.age,
    lifestyle: userContext?.lifestyle,
    goals: userContext?.goals,
    compliance: userContext?.protocol_adherence,
  })

  useEffect(() => {
    let cancelled = false

    async function loadTips() {
      setLoading(true)
      try {
        const result = await generateHealthTips(biomarkers, userContext)
        if (cancelled) return

        if (result.status === 'pending') {
          setTips([])
          setPendingJobId(result.jobId || null)
          setPendingMessage(result.message || 'Premium analysis is processing. Please check back in about 10 minutes.')
          return
        }

        setPendingJobId(null)
        setPendingMessage('')
        setTips(sortTipsByDifficulty(result.tips || []))
      } catch (error) {
        console.error('Failed to load health tips:', error)
      } finally {
        if (!cancelled) {
          setLoading(false)
        }
      }
    }

    if (biomarkers?.length > 0) {
      loadTips()
    }

    return () => {
      cancelled = true
    }
  }, [biomarkersKey, userContextKey])

  useEffect(() => {
    if (!pendingJobId) return

    let attempts = 0
    let timer = null
    let cancelled = false

    const poll = async () => {
      attempts += 1
      const result = await getHealthTipsJob(pendingJobId)
      if (cancelled) return

      if (result.status === 'ready') {
        setTips(sortTipsByDifficulty(result.tips || []))
        setPendingJobId(null)
        setPendingMessage('')
        return
      }

      setPendingMessage(result.message || pendingMessage)
      if (attempts < 30) {
        timer = setTimeout(poll, 20000)
      }
    }

    timer = setTimeout(poll, 20000)
    return () => {
      cancelled = true
      if (timer) clearTimeout(timer)
    }
  }, [pendingJobId])

