          </div>
        </div>
      </div>

      {/* Top Improvers */}
      {analysis.topImprovers.length > 0 && (
        <div>
          <h3 style={{ fontSize: '18px', fontWeight: 700, color: '#0f172a', marginBottom: '12px', display: 'flex', alignItems: 'center', gap: '8px' }}>
            <TrendingUp size={20} style={{ color: '#16a34a' }} />
            Top Improvers
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {analysis.topImprovers.map((trend) => (
              <div
                key={trend.biomarkerId}
                style={{
                  padding: '12px 16px',
                  background: '#f0fdf4',
                  border: '1px solid #dcfce7',
                  borderRadius: '8px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  cursor: 'pointer',
                  transition: 'all 200ms'
                }}
                onClick={() => setSelectedBiomarker(trend.biomarkerId)}
                onMouseEnter={(e) => {
                  e.currentTarget.style.background = '#dcfce7'
                  e.currentTarget.style.borderColor = '#bbf7d0'
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.background = '#f0fdf4'
                  e.currentTarget.style.borderColor = '#dcfce7'
                }}
              >
                <div>
                  <div style={{ fontSize: '14px', fontWeight: 600, color: '#166534' }}>
                    {trend.biomarkerName}
                  </div>
                  <div style={{ fontSize: '12px', color: '#059669', marginTop: '2px' }}>
                    Latest: {trend.latestValue} | Avg: {trend.averageValue}
                  </div>
                </div>
                <div style={{
                  fontSize: '16px',
                  fontWeight: 700,
                  color: '#16a34a',
                  textAlign: 'right'
                }}>
                  +{trend.percentChange.toFixed(1)}%
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Top Decliners */}
      {analysis.topDecliners.length > 0 && (
        <div>
          <h3 style={{ fontSize: '18px', fontWeight: 700, color: '#0f172a', marginBottom: '12px', display: 'flex', alignItems: 'center', gap: '8px' }}>
            <TrendingDown size={20} style={{ color: '#dc2626' }} />
            Needs Attention
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {analysis.topDecliners.map((trend) => (
              <div
                key={trend.biomarkerId}
                style={{
                  padding: '12px 16px',
                  background: '#fee2e2',
                  border: '1px solid #fecaca',
                  borderRadius: '8px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  cursor: 'pointer',
                  transition: 'all 200ms'
                }}
                onClick={() => setSelectedBiomarker(trend.biomarkerId)}
                onMouseEnter={(e) => {
                  e.currentTarget.style.background = '#fecaca'
                  e.currentTarget.style.borderColor = '#fca5a5'
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.background = '#fee2e2'
                  e.currentTarget.style.borderColor = '#fecaca'
                }}
              >
                <div>
                  <div style={{ fontSize: '14px', fontWeight: 600, color: '#991b1b' }}>
                    {trend.biomarkerName}
                  </div>
                  <div style={{ fontSize: '12px', color: '#dc2626', marginTop: '2px' }}>
                    Latest: {trend.latestValue} | Avg: {trend.averageValue}
                  </div>
                </div>
                <div style={{
                  fontSize: '16px',
                  fontWeight: 700,
                  color: '#dc2626',
                  textAlign: 'right'
                }}>
                  {trend.percentChange.toFixed(1)}%
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Volatile Markers */}
      {analysis.mostVolatile.length > 0 && (
        <div>
          <h3 style={{ fontSize: '18px', fontWeight: 700, color: '#0f172a', marginBottom: '12px', display: 'flex', alignItems: 'center', gap: '8px' }}>
            <AlertTriangle size={20} style={{ color: '#f59e0b' }} />
            Volatile Markers
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {analysis.mostVolatile.map((trend) => (
              <div
                key={trend.biomarkerId}
                style={{
                  padding: '12px 16px',
                  background: '#fef3c7',
                  border: '1px solid #fde68a',
                  borderRadius: '8px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between'
                }}
              >
                <div>
                  <div style={{ fontSize: '14px', fontWeight: 600, color: '#78350f' }}>
                    {trend.biomarkerName}
                  </div>
                  <div style={{ fontSize: '12px', color: '#92400e', marginTop: '2px' }}>
                    Consider more frequent monitoring
                  </div>
                </div>
                <div style={{
                  fontSize: '12px',
                  fontWeight: 600,
                  color: '#78350f',
                  textAlign: 'right'
                }}>
                  High variability
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Overall Status */}
      <div style={{
        padding: '16px',
        background: analysis.overallStatus === 'improving' ? '#f0fdf4' :
          analysis.overallStatus === 'declining' ? '#fee2e2' : '#f0f9ff',
        border: `2px solid ${
          analysis.overallStatus === 'improving' ? '#dcfce7' :
            analysis.overallStatus === 'declining' ? '#fecaca' : '#bfdbfe'
        }`,
        borderRadius: '12px',
        textAlign: 'center'
      }}>
        <div style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: '8px',
          fontSize: '16px',
          fontWeight: 700,
          color: analysis.overallStatus === 'improving' ? '#166534' :
            analysis.overallStatus === 'declining' ? '#991b1b' : '#0c2a47'
        }}>
          {analysis.overallStatus === 'improving' ? (
            <>
              <CheckCircle size={20} />
              Overall Trend: Improving
            </>
          ) : analysis.overallStatus === 'declining' ? (
            <>
              <AlertTriangle size={20} />
              Overall Trend: Declining
            </>
          ) : (
            <>
              <Activity size={20} />
              Overall Trend: Stable
            </>
          )}
        </div>
        <p style={{
          fontSize: '13px',
          margin: '8px 0 0 0',
          opacity: 0.8,
          color: 'inherit'
        }}>
          Based on {analysis.improvingCount + analysis.stableCount + analysis.decliningCount} biomarkers tracked
        </p>
      </div>
    </div>
  )
}

import React from 'react'
import { motion } from 'framer-motion'
import { Clock, CheckCircle, AlertCircle, ArrowRight } from 'lucide-react'

export default function AssignmentCard({ assignment, onClick, animated = true, delay = 0 }) {
  const statusColors = {
    pending: 'bg-amber-50 text-amber-700 border-amber-200',
    in_progress: 'bg-blue-50 text-blue-700 border-blue-200',
    completed: 'bg-emerald-50 text-emerald-700 border-emerald-200',
    overdue: 'bg-rose-50 text-rose-700 border-rose-200',
  }

  const statusIcons = {
    pending: Clock,
    in_progress: AlertCircle,
    completed: CheckCircle,
    overdue: AlertCircle,
  }

  const status = assignment.status || 'pending'
  const StatusIcon = statusIcons[status] || Clock
  const statusClass = statusColors[status] || statusColors.pending

  const dueDate = assignment.due_date ? new Date(assignment.due_date).toLocaleDateString() : 'No due date'
  const priority = assignment?.priority

  const impactTone = {
    critical: 'text-rose-600 border-rose-200 bg-rose-50',
    high: 'text-orange-600 border-orange-200 bg-orange-50',
    medium: 'text-blue-600 border-blue-200 bg-blue-50',
    low: 'text-slate-500 border-slate-200 bg-slate-50',
  }

  const urgencyTone = {
    overdue: 'text-rose-600 font-bold',
    today: 'text-orange-600 font-bold',
    soon: 'text-amber-600',
    normal: 'text-slate-400',
  }

  const animationProps = animated
    ? {
      initial: { opacity: 0, x: -20 },
      whileInView: { opacity: 1, x: 0 },
      viewport: { once: true, margin: '-100px' },
      transition: { duration: 0.4, delay, ease: [0.16, 1, 0.3, 1] },
      whileHover: { x: 4 },
    }
    : {}

  const WrapperComponent = animated ? motion.div : 'div'

  return (
    <WrapperComponent
      className={`cabinet-card p-4 flex items-start gap-4 transition-all duration-300 group ${onClick ? 'cursor-pointer cabinet-card-hover' : ''}`}
      onClick={onClick}
      onKeyDown={(event) => {
        if (!onClick) return
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault()
          onClick()
        }
      }}
      role={onClick ? 'button' : undefined}
      tabIndex={onClick ? 0 : undefined}
      {...animationProps}
    >
      {/* Icon */}
      <motion.div
        className={`p-2.5 rounded-lg flex-shrink-0 ${statusClass} border`}
        whileHover={{ scale: 1.1, rotate: 5 }}
        whileTap={{ scale: 0.95 }}
        transition={{ duration: 0.2 }}
      >
        <StatusIcon className="w-5 h-5" />
      </motion.div>

      {/* Content */}
      <div className="flex-1 min-w-0">
        <h3 className="text-slate-900 font-semibold truncate group-hover:text-emerald-700 transition text-sm">
          {assignment.title || assignment.name || 'Untitled Assignment'}
        </h3>
        <p className="text-slate-500 text-xs truncate mb-2">
          {assignment.description || 'Complete this assignment'}
        </p>
        <div className="flex flex-wrap items-center gap-2">
          <p className="text-slate-400 text-xs">{dueDate}</p>
          {priority?.urgency && (
            <motion.span
              className={`text-[11px] font-semibold ${urgencyTone[priority.urgency] || urgencyTone.normal}`}
              animate={priority.urgency === 'overdue' ? { opacity: [0.7, 1, 0.7] } : {}}
              transition={priority.urgency === 'overdue' ? { duration: 2, repeat: Infinity } : {}}
            >
              {priority.urgency.toUpperCase()}
            </motion.span>
          )}
          {priority?.impact && (
            <span className={`text-[11px] border rounded px-1.5 py-0.5 ${impactTone[priority.impact] || impactTone.low}`}>
              {priority.impact.toUpperCase()}
            </span>
          )}
        </div>
      </div>

      {/* Status Badge & Arrow */}
      <div className="flex items-center gap-2 flex-shrink-0">
        {priority?.score != null && (
          <motion.span
            className="px-2.5 py-1 rounded-lg text-xs font-semibold bg-emerald-50 border border-emerald-200 text-emerald-600"
            whileHover={{ scale: 1.1 }}
          >
            #{priority.score}
          </motion.span>
        )}
        <span className={`px-2.5 py-1 rounded-lg text-xs font-semibold ${statusClass} border`}>
          {status.replace('_', ' ').toUpperCase()}
        </span>
        <motion.div
          animate={{ x: [0, 3, 0] }}
          transition={{ duration: 2, repeat: Infinity }}
          className="text-slate-400 group-hover:text-emerald-600 transition"
        >
          <ArrowRight className="w-4 h-4" />
        </motion.div>
      </div>
    </WrapperComponent>
  )
}

import React, { useMemo } from 'react'
import { motion } from 'framer-motion'
import { TrendingUp, TrendingDown, Minus, CheckCircle, AlertTriangle, XCircle, Calendar } from 'lucide-react'
import AnimatedCounter from './AnimatedCounter'

export default function HealthChart({ progress }) {
  const normalizeStatus = (status) => {
    const value = String(status || '').toLowerCase()
    if (value.includes('optimal') || value.includes('normal')) return 'optimal'
    if (value.includes('border') || value.includes('warn')) return 'warning'
    if (value.includes('critical') || value.includes('deficient') || value.includes('elevated')) return 'critical'
    return 'warning'
  }

  const healthMetrics = useMemo(() => {
    if (!progress || progress.length === 0) return null

    const uploadsWithBiomarkers = progress.filter(
      (upload) => Array.isArray(upload?.biomarkers) && upload.biomarkers.length > 0
    )
    if (uploadsWithBiomarkers.length === 0) return null

    const latest = uploadsWithBiomarkers[uploadsWithBiomarkers.length - 1]
    const previous = uploadsWithBiomarkers.length > 1 ? uploadsWithBiomarkers[uploadsWithBiomarkers.length - 2] : null

    const latestStats = {
      total: latest.biomarkers?.length || 0,
      optimal: latest.biomarkers?.filter(b => normalizeStatus(b.status) === 'optimal').length || 0,
      warning: latest.biomarkers?.filter(b => normalizeStatus(b.status) === 'warning').length || 0,
      critical: latest.biomarkers?.filter(b => normalizeStatus(b.status) === 'critical').length || 0,
    }

    const previousStats = previous ? {
      total: previous.biomarkers?.length || 0,
      optimal: previous.biomarkers?.filter(b => normalizeStatus(b.status) === 'optimal').length || 0,
      warning: previous.biomarkers?.filter(b => normalizeStatus(b.status) === 'warning').length || 0,
      critical: previous.biomarkers?.filter(b => normalizeStatus(b.status) === 'critical').length || 0,
    } : null

    // Calculate trend
    let trend = 'stable'
    let trendDirection = null
    if (previousStats) {
      const currentOptimalPercent = (latestStats.optimal / latestStats.total) * 100
      const previousOptimalPercent = (previousStats.optimal / previousStats.total) * 100
      const currentCriticalPercent = (latestStats.critical / latestStats.total) * 100
      const previousCriticalPercent = (previousStats.critical / previousStats.total) * 100

      if (currentOptimalPercent > previousOptimalPercent + 5) {
        trend = 'improving'
        trendDirection = 'up'
      } else if (currentCriticalPercent > previousCriticalPercent + 5) {
        trend = 'declining'
        trendDirection = 'down'
      }
    }

    return {
      latest: latestStats,
      previous: previousStats,
      trend,
      trendDirection,
      testDate: latest.test_date || latest.created_at?.split('T')[0] || null,
      totalLabs: uploadsWithBiomarkers.length,
      timeline: uploadsWithBiomarkers.slice(-5).reverse(),
    }
  }, [progress])

  const getStatusIcon = (status) => {
    switch (status) {
    case 'optimal': return <CheckCircle className="w-4 h-4 text-green-600" />
    case 'warning': return <AlertTriangle className="w-4 h-4 text-yellow-600" />
    case 'critical': return <XCircle className="w-4 h-4 text-red-600" />
    default: return <Minus className="w-4 h-4 text-gray-400" />
    }
  }

  const getTrendIcon = (trend) => {
    switch (trend) {
    case 'improving': return <TrendingUp className="w-5 h-5 text-green-600" />
    case 'declining': return <TrendingDown className="w-5 h-5 text-red-600" />
    default: return <Minus className="w-5 h-5 text-gray-400" />
    }
  }

  const getTrendColor = (trend) => {
    switch (trend) {
    case 'improving': return 'text-green-700 bg-green-50 border-green-200'
    case 'declining': return 'text-red-700 bg-red-50 border-red-200'
    default: return 'text-gray-700 bg-gray-50 border-gray-200'
    }
  }

  if (!healthMetrics) {
    return (
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true, margin: '-100px' }}
        transition={{ duration: 0.5 }}
        className="flex flex-col items-center justify-center py-12 text-slate-400"
      >
        <Calendar className="w-8 h-8 mb-3" />
        <p className="mb-2">No health data available yet</p>
        <p className="text-sm">Upload your lab results to see trends and insights</p>
      </motion.div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Overall Health Trend */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true, margin: '-100px' }}
        transition={{ duration: 0.5 }}
        className={`rounded-xl border p-6 ${getTrendColor(healthMetrics.trend)} ${
          healthMetrics.trend === 'improving' ? 'cabinet-glow' : ''
        } transition-all duration-300`}
      >
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            {getTrendIcon(healthMetrics.trend)}
            <div>
              <h3 className="font-semibold text-lg">
                {healthMetrics.trend === 'improving' && 'Health Improving'}
                {healthMetrics.trend === 'declining' && 'Health Declining'}
                {healthMetrics.trend === 'stable' && 'Health Stable'}
              </h3>
              <p className="text-sm opacity-80">
                Based on your latest lab results
                {healthMetrics.testDate && ` from ${new Date(healthMetrics.testDate).toLocaleDateString()}`}
              </p>
            </div>
          </div>
          <div className="text-right">
            <div className="text-2xl font-bold">
              {healthMetrics.latest.total > 0
                ? Math.round((healthMetrics.latest.optimal / healthMetrics.latest.total) * 100)
                : 0}%
            </div>
            <div className="text-xs opacity-70">Optimal biomarkers</div>
          </div>
        </div>
      </motion.div>

      {/* Biomarker Status Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-100px' }}
          transition={{ duration: 0.5, delay: 0.1 }}
          whileHover={{ y: -4, boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }}
          className="bg-gradient-to-br from-green-50 to-emerald-50 border border-green-200 rounded-xl p-6 transition-all duration-300"
        >
          <div className="flex items-center gap-2 mb-3">
            {getStatusIcon('optimal')}
            <span className="font-semibold text-green-800">Optimal</span>
          </div>
          <div className="text-3xl font-bold text-green-700 mb-1">
            <AnimatedCounter value={healthMetrics.latest.optimal} />
          </div>
          <div className="text-sm text-green-600">of {healthMetrics.latest.total} biomarkers</div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-100px' }}
          transition={{ duration: 0.5, delay: 0.15 }}
          whileHover={{ y: -4, boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }}
          className="bg-gradient-to-br from-yellow-50 to-amber-50 border border-yellow-200 rounded-xl p-6 transition-all duration-300"
        >
          <div className="flex items-center gap-2 mb-3">
            {getStatusIcon('warning')}
            <span className="font-semibold text-yellow-800">Borderline</span>
          </div>
          <div className="text-3xl font-bold text-yellow-700 mb-1">
            <AnimatedCounter value={healthMetrics.latest.warning} />
          </div>
          <div className="text-sm text-yellow-600">need attention</div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-100px' }}
          transition={{ duration: 0.5, delay: 0.2 }}
          whileHover={{ y: -4, boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }}
          className="bg-gradient-to-br from-red-50 to-rose-50 border border-red-200 rounded-xl p-6 transition-all duration-300"
        >
          <div className="flex items-center gap-2 mb-3">
            {getStatusIcon('critical')}
            <span className="font-semibold text-red-800">Critical</span>
          </div>
          <div className="text-3xl font-bold text-red-700 mb-1">
            <AnimatedCounter value={healthMetrics.latest.critical} />
          </div>
          <div className="text-sm text-red-600">require action</div>
        </motion.div>
      </div>

      {/* Progress Timeline */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true, margin: '-100px' }}
        transition={{ duration: 0.5, delay: 0.25 }}
        className="cabinet-card p-6"
      >
        <h4 className="font-semibold text-slate-900 mb-4 flex items-center gap-2">
          <Calendar className="w-5 h-5 text-emerald-600" />
          Lab Results Timeline
        </h4>
        <div className="space-y-2">
          {healthMetrics.timeline.map((lab, index) => {
            const optimalCount = lab.biomarkers?.filter(b => normalizeStatus(b.status) === 'optimal').length || 0
            const totalCount = lab.biomarkers?.length || 0
            const percentage = totalCount > 0 ? Math.round((optimalCount / totalCount) * 100) : 0

            return (
              <motion.div
                key={index}
                initial={{ opacity: 0, x: -10 }}
                whileInView={{ opacity: 1, x: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.3, delay: index * 0.05 }}
                whileHover={{ x: 4, boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                className="flex items-center justify-between py-3 px-4 bg-gradient-to-r from-slate-50 to-white rounded-lg border border-slate-100 transition-all"
              >
                <div className="flex items-center gap-3">
                  <motion.div
                    animate={{ scale: [1, 1.2, 1] }}
                    transition={{ duration: 2, repeat: Infinity }}
                    className="w-2.5 h-2.5 bg-emerald-500 rounded-full"
                  />
                  <span className="text-sm font-medium text-slate-700">
                    {(() => {
                      const dateStr = lab.test_date || lab.created_at
                      if (!dateStr) return 'Recently uploaded'
                      try {
                        return new Date(dateStr).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
                      } catch {
                        return 'Recently uploaded'
                      }
                    })()}
                  </span>
                </div>
                <div className="flex items-center gap-3">
                  <div className="text-sm font-semibold text-slate-900">{optimalCount}/{totalCount}</div>
                  <div className={`text-xs px-3 py-1 rounded-full font-semibold ${
                    percentage >= 70 ? 'bg-green-100 text-green-700' :
                      percentage >= 40 ? 'bg-yellow-100 text-yellow-700' :
                        'bg-red-100 text-red-700'
                  }`}>
                    {percentage}%
                  </div>
                </div>
              </motion.div>
            )
          })}
        </div>
        <motion.div
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5, delay: 0.5 }}
          className="mt-4 pt-4 border-t border-slate-200 text-xs text-slate-500 text-center"
        >
          Total lab uploads: <span className="font-semibold text-slate-700">{healthMetrics.totalLabs}</span>
        </motion.div>
      </motion.div>
    </div>
  )
}

import { motion } from 'framer-motion'
import { Heart, CreditCard, Upload, Clock, Target, TrendingUp } from 'lucide-react'

export default function MetricBar({ stats, uploadCount, uploadLimit, subStatus, isPremium, latestCheckin }) {
  const getPlanColor = (plan) => {
    if (plan === 'active' || plan === 'personal_pro') return 'bg-emerald-100 text-emerald-700'
    if (plan === 'enterprise') return 'bg-blue-100 text-blue-700'
    return 'bg-slate-100 text-slate-700'
  }

  const getPlanName = (plan) => {
    if (plan === 'active' || plan === 'personal_pro') return 'Premium'
    if (plan === 'enterprise') return 'Enterprise'
    return 'Free'
  }

  const getCheckInStatus = (latestCheckin) => {
    if (!latestCheckin) return { label: 'No check-in', color: 'bg-amber-100 text-amber-700' }
    const weekStart = new Date(latestCheckin.week_start)
    const now = new Date()
    const daysAgo = Math.floor((now - weekStart) / (1000 * 60 * 60 * 24))
    if (daysAgo > 7) return { label: 'Check-in overdue', color: 'bg-red-100 text-red-700' }
    return { label: `Week ${Math.floor(daysAgo / 7) + 1}`, color: 'bg-emerald-100 text-emerald-700' }
  }

